	public void writeTasks(CompoundTag tag, HolderLookup.Provider provider) {
		ListTag t = new ListTag();
		for (Task task : tasks) {
			TaskType type = task.getType();
			SNBTCompoundTag nbt3 = new SNBTCompoundTag();
			nbt3.putString("id", task.getCodeString());
